-- Both T1 and T2 run this concurrently, at REPEATABLE READ,
-- against a flight with capacity 1 and no bookings yet:

BEGIN ISOLATION LEVEL REPEATABLE READ;
SELECT capacity - (SELECT count(*) FROM bookings WHERE flight_id = 1) AS seats_remaining
FROM flights WHERE id = 1;
