exercises.solutionCode:
-- fragment: customer ids are placeholders
-- Fix 1: SERIALIZABLE, with a retry loop in the application
BEGIN ISOLATION LEVEL SERIALIZABLE;
SELECT capacity - (SELECT count(*) FROM bookings WHERE flight_id = 1) AS seats_remaining
FROM flights WHERE id = 1;
-- application: only continue if seats_remaining > 0
INSERT INTO bookings (flight_id, customer_id) VALUES (1, /* customer */);
COMMIT;
-- if this raises a serialization_failure error, the application must
-- catch it and retry the entire transaction from BEGIN

-- Fix 2: lock the flight row first, at the default READ COMMITTED level
BEGIN;
SELECT capacity FROM flights WHERE id = 1 FOR UPDATE;
-- a concurrent booking for the same flight waits here until this
-- transaction commits or rolls back
SELECT count(*) FROM bookings WHERE flight_id = 1;
-- a new statement takes a new snapshot, so it sees any booking
-- the other transaction just committed
-- application: only continue if count < capacity
INSERT INTO bookings (flight_id, customer_id) VALUES (1, /* customer */);
COMMIT;
